// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 blockNum) public {
        bound(blockNum, 1, 2**30);
        vm.roll(blockNum);

        address caller1 = address(0x1001);
        address caller2 = address(0x1002);
        vm.deal(caller1, 10 ether);
        vm.deal(caller2, 10 ether);

        vm.startPrank(caller1);
        (bool succ1, ) = address(c).call{value: 10 ether}("");
        vm.stopPrank();

        vm.startPrank(caller2);
        (bool succ2, ) = address(c).call{value: 10 ether}("");
        vm.stopPrank();

        assertTrue(!succ1 || !succ2);
    }
}
